-- DATOS HISTORICOS DE PRODUCCION REAL (EIU UAGRM 2021-2025)
-- Carga automatica de periodos, clientes, proformas, ordenes y consumos reales
-- Generado para inicializacion automatica de PostgreSQL en produccion (Azure)
-- ============================================================================

BEGIN;

-- 1. Periodos Academicos Adicionales (2021 - 2027)
ON CONFLICT (id_periodo) DO NOTHING;

SELECT setval(pg_get_serial_sequence('periodo_academico', 'id_periodo'), coalesce(max(id_periodo), 1)) FROM periodo_academico;

-- 2. Clientes Institucionales y Facultades UAGRM
ON CONFLICT (id_cliente) DO NOTHING;

SELECT setval(pg_get_serial_sequence('cliente', 'id_cliente'), coalesce(max(id_cliente), 1)) FROM cliente;

-- 3. Proformas Historicas Aprobadas (607 registros)
ON CONFLICT (id_proforma) DO NOTHING;

SELECT setval(pg_get_serial_sequence('proforma', 'id_proforma'), coalesce(max(id_proforma), 1)) FROM proforma;

-- 4. Ordenes de Trabajo Litograficas (604 registros)
ON CONFLICT (id_orden) DO NOTHING;

SELECT setval(pg_get_serial_sequence('orden_trabajo', 'id_orden'), coalesce(max(id_orden), 1)) FROM orden_trabajo;

-- 5. Consumos Reales y Mermas (2055 registros para Machine Learning)
ON CONFLICT (id_consumo) DO NOTHING;

ON CONFLICT (id_consumo) DO NOTHING;

ON CONFLICT (id_consumo) DO NOTHING;

ON CONFLICT (id_consumo) DO NOTHING;

ON CONFLICT (id_consumo) DO NOTHING;

SELECT setval(pg_get_serial_sequence('consumo_real', 'id_consumo'), coalesce(max(id_consumo), 1)) FROM consumo_real;

COMMIT;
